Script:
MetadataMenu = {
    descriptions: {
        AI: "Artificial intelligence provider, model and prompt-management operations.",
        AppSecurity: "Application-scoped roles, privileges, users and authorization relationships.",
        B2B: "Business-to-business companies, buckets, transactions, funding, offers and related portal data.",
        ContentManagement: "Applications, pages, layouts, templates, components, resources, cultures and rendered content.",
        DocumentManagement: "Folders, files, file content and the events and permissions attached to document paths.",
        Logging: "Persisted log entries and supporting diagnostic data exposed by the logging service.",
        Mail: "Mail servers, senders, receivers, queued messages and sent or received email records.",
        Packaging: "Package import, export and package-item contracts used to move managed application data.",
        Security: "SSO users, roles, privileges, tenants and the security identities shared by applications.",
        Workflow: "Flow definitions, instances, workflow events, calendars, schedules and execution data."
    },

    init: async function (app, container) {
        container = container || $(".component[name=MetadataMenu]");
        container.empty();

        const serviceDocument = await api.get("");
        const contexts = (serviceDocument.value || [])
            .filter(item => item.kind === "Context")
            .sort((left, right) => left.name.localeCompare(right.name));

        const grid = $('<div class="docs-nav-grid docs-nav-scope-grid metadata-context-grid"></div>');
        grid.attr("data-columns", Math.min(3, Math.max(1, contexts.length)));
        container.append(grid);

        for (const context of contexts) {
            MetadataMenu.createItem(context, grid);
        }
    },

    createItem: function (context, parentElement) {
        const contextPath = "/Api/" + encodeURIComponent(context.url);
        const metadataPath = contextPath + "/$metadata";
        const card = $('<article class="docs-nav-card docs-nav-scope metadata-context-card"></article>')
            .attr("data-context", context.name);
        const title = $('<h3 class="docs-nav-title"></h3>');
        const titleLink = $('<a class="metadata-context-link" target="_blank" rel="noopener"></a>')
            .attr("href", contextPath)
            .text(context.name);
        const description = $('<p class="docs-nav-description"></p>')
            .text(MetadataMenu.descriptions[context.name] || ("Explore the " + context.name + " API context."));
        const footer = $('<div class="docs-nav-footer"></div>');
        const actions = $('<div class="docs-nav-actions"></div>');

        title.append(titleLink);
        actions.append(MetadataMenu.createLink("Context", contextPath, "metadata-context-link"));
        actions.append(MetadataMenu.createLink("Metadata", metadataPath, "metadata-description-link"));

        if (context.swaggerDef) {
            actions.append(MetadataMenu.createLink("Swagger", context.swaggerDef, "metadata-swagger-link"));
        }

        footer.append(actions);
        card.append(title, description, footer);
        parentElement.append(card);
    },

    createLink: function (text, href, cssClass) {
        const link = $('<a class="docs-nav-command" target="_blank" rel="noopener"></a>')
            .addClass(cssClass)
            .attr("href", href)
            .attr("aria-label", text + " " + href);
        link.append($('<span class="docs-nav-command-name"></span>').text(text));
        return link;
    }
};
